const char* errorName(Error e) {
  switch (e) {
    case Error::Ok: return "ok";
    case Error::TooLarge: return "too large";
    case Error::Malformed: return "malformed";
    case Error::UnsupportedVersion: return "unsupported version";
    case Error::BadDigest: return "bad digest";
    case Error::TooManyTracks: return "too many tracks";
    case Error::TooManySegments: return "too many segments";
    case Error::TooManyLamps: return "too many lamps";
    case Error::BadCurve: return "bad curve";
    case Error::BadTrackShape: return "bad track shape";
    case Error::OutOfRange: return "out of range";
    case Error::PixelOutOfRange: return "pixel out of range";
    case Error::DuplicatePixel: return "duplicate pixel";
    case Error::BadTrackRef: return "bad track reference";
    case Error::NoDefinition: return "no definition";
    case Error::DigestMismatch: return "digest mismatch";
  }
  return "unknown";
}

pb_istream_t streamFrom(bool (*read)(pb_istream_t*, pb_byte_t*, size_t), void* state, size_t length) {
  pb_istream_t in;
  memset(&in, 0, sizeof(in));
  in.callback = read;
  in.state = state;
  in.bytes_left = length;
  return in;
}

Error decode(pb_istream_t* stream, Frame& frame, Definition& staged) {
  if (stream->bytes_left > MAX_RESPONSE_BYTES) return Error::TooLarge;
  memset(&frame, 0, sizeof(frame));
  staged.trackCount = 0;
  staged.segmentCount = 0;
  Context c = {&frame, &staged, Error::Ok, 0};
  kwm_RenderResponse msg = kwm_RenderResponse_init_zero;
  msg.lamps.funcs.decode = readLamp;
  msg.lamps.arg = &c;
  msg.definition.tracks.funcs.decode = readTrack;
  msg.definition.tracks.arg = &c;
  msg.definition.segments.funcs.decode = readSegment;
  msg.definition.segments.arg = &c;
  if (!pb_decode(stream, kwm_RenderResponse_fields, &msg)) {
    return c.error != Error::Ok ? c.error : Error::Malformed;
  }
  if (msg.contract_version != CONTRACT_VERSION) return Error::UnsupportedVersion;
  uint8_t any = 0;
  for (size_t i = 0; i < DIGEST_BYTES; i++) any |= msg.digest[i];
  if (!any) return Error::BadDigest;
  memcpy(frame.digest, msg.digest, DIGEST_BYTES);
  const uint32_t weather = enumValue(msg.weather);
  if (weather > 2 || msg.brightness > 255) return Error::OutOfRange;
  frame.contractVersion = msg.contract_version;
  frame.weather = static_cast<Weather>(weather);
  frame.brightness = static_cast<uint8_t>(msg.brightness);
  frame.hasDefinition = msg.has_definition;
  if (!frame.hasDefinition) return Error::Ok;
  if (staged.trackCount == 0) return Error::BadTrackShape;
  uint16_t next = 0;
  for (uint8_t t = 0; t < staged.trackCount; t++) {
    if (next + staged.tracks[t].segmentCount > staged.segmentCount) return Error::BadTrackShape;
    staged.tracks[t].firstSegment = next;
    next = static_cast<uint16_t>(next + staged.tracks[t].segmentCount);
  }
  if (next != staged.segmentCount) return Error::BadTrackShape;
  return Error::Ok;
}

Error decodeBuffer(const uint8_t* data, size_t length, Frame& frame, Definition& staged) {
  if (length > MAX_RESPONSE_BYTES) return Error::TooLarge;
  const uint8_t* cursor = data;
  pb_istream_t in = streamFrom(readBuffer, &cursor, length);
  return decode(&in, frame, staged);
}

Error validateLamps(const Frame& frame, const Definition& inEffect) {
  for (uint8_t i = 0; i < frame.lampCount; i++) {
    if (frame.lamps[i].track >= inEffect.trackCount) return Error::BadTrackRef;
  }
  return Error::Ok;
}

